package edu.fuzzy;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static edu.fuzzy.AuditProtocol.*;
class CoreLogicTest {
 @TempDir Path temp;
 private final IdentityService identity=new IdentityService();
 @Test void fuzzyExactNoisyWrongAndBoundary(){assertEquals(8,identity.match(IdentityService.TEMPLATE,IdentityService.TEMPLATE).overlap());assertTrue(identity.match(IdentityService.TEMPLATE,"11,22,33,44,55,66,91,92").accepted());assertFalse(identity.match(IdentityService.TEMPLATE,"11,22,33,44,91,92,93,94").accepted());assertFalse(identity.match(IdentityService.TEMPLATE,"11,22,33,44,55").accepted());assertTrue(identity.match(IdentityService.TEMPLATE,"11,22,33,44,55,66").accepted());assertFalse(identity.match(IdentityService.TEMPLATE,"11,11,11,11,11,11").accepted());}
 @Test void malformedIdentityRejected(){for(String s:new String[]{"", " ","11,22,x","-1,22","1," ,"1,".repeat(40),"9".repeat(501)})assertThrows(IllegalArgumentException.class,()->identity.parse(s));}
 @Test void otpIncorrectExpiryReuseAndLockout(){OtpService service=new OtpService();var s=service.issue("x@demo.local",1000);assertThrows(IllegalArgumentException.class,()->service.verify(s,"bad",1001));service.verify(s,s.code,1002);assertThrows(IllegalArgumentException.class,()->service.verify(s,s.code,1003));var expired=service.issue("x@demo.local",1000);assertThrows(IllegalArgumentException.class,()->service.verify(expired,expired.code,181001));var locked=service.issue("x@demo.local",1000);for(int i=0;i<5;i++)assertThrows(IllegalArgumentException.class,()->service.verify(locked,"bad",1001));assertThrows(IllegalArgumentException.class,()->service.verify(locked,locked.code,1001));}
 @Test void aesGcmBinaryRoundtripTamperAadAndRestart()throws Exception{CryptoService c=new CryptoService(temp.toString());byte[]key=c.random(32),plain=c.random(180000);String id=UUID.randomUUID().toString();byte[] encrypted=c.encrypt(plain,key,id+":1");assertArrayEquals(plain,c.decrypt(encrypted,key,id+":1"));assertFalse(Arrays.equals(Arrays.copyOf(encrypted,plain.length),plain));assertThrows(Exception.class,()->c.decrypt(encrypted,key,id+":2"));String wrapped=c.wrap(key,"file:"+id);CryptoService restarted=new CryptoService(temp.toString());assertArrayEquals(key,restarted.unwrap(wrapped,"file:"+id));assertThrows(Exception.class,()->restarted.unwrap(wrapped,"file:wrong"));encrypted[30]^=1;assertThrows(Exception.class,()->c.decrypt(encrypted,key,id+":1"));assertThrows(IllegalArgumentException.class,()->c.object("../../escape"));}
 @Test void actualDiskProofPassCorruptionMissingTruncation()throws Exception{AuditProtocol p=new AuditProtocol();byte[]bytes=new byte[150000];new Random(42).nextBytes(bytes);String id=UUID.randomUUID().toString();Manifest m=p.manifest(id,1,bytes);Challenge c=p.challenge("audit",m,"FULL",1000);Path f=temp.resolve("object");Files.write(f,bytes);assertTrue(p.verify(c,p.respond(c,f),m,1001).passed());String before=m.blocks().get(0).digest();bytes[29]^=1;Files.write(f,bytes);assertFalse(p.verify(c,p.respond(c,f),m,1001).passed());assertEquals(before,m.blocks().get(0).digest());Files.write(f,Arrays.copyOf(bytes,300));assertFalse(p.verify(c,p.respond(c,f),m,1001).passed());Files.delete(f);assertThrows(java.io.IOException.class,()->p.respond(c,f));}
 @Test void wrongNonceFileVersionExpiryAndBlockSetsRejected()throws Exception{AuditProtocol p=new AuditProtocol();byte[]bytes=new byte[140000];Manifest m=p.manifest("file",2,bytes);Challenge c=p.challenge("audit",m,"FULL",1000);Path f=temp.resolve("object");Files.write(f,bytes);Response r=p.respond(c,f);assertTrue(p.verify(c,r,m,1001).passed());for(Response bad:List.of(new Response("other",r.nonce(),r.fileId(),r.version(),r.objectLength(),r.blocks()),new Response(r.auditId(),"wrong",r.fileId(),r.version(),r.objectLength(),r.blocks()),new Response(r.auditId(),r.nonce(),"wrong",r.version(),r.objectLength(),r.blocks()),new Response(r.auditId(),r.nonce(),r.fileId(),3,r.objectLength(),r.blocks()),new Response(r.auditId(),r.nonce(),r.fileId(),r.version(),r.objectLength()+1,r.blocks()),new Response(r.auditId(),r.nonce(),r.fileId(),r.version(),r.objectLength(),r.blocks().subList(0,2)),new Response(r.auditId(),r.nonce(),r.fileId(),r.version(),r.objectLength(),List.of(r.blocks().get(0),r.blocks().get(0),r.blocks().get(2))),new Response(r.auditId(),r.nonce(),r.fileId(),r.version(),r.objectLength(),List.of(r.blocks().get(0),r.blocks().get(1),new ResponseBlock(99,new byte[1])))))assertFalse(p.verify(c,bad,m,1001).passed());assertFalse(p.verify(c,r,m,c.expiresAt()+1).passed());var mutated=new ArrayList<>(r.blocks());mutated.set(0,new ResponseBlock(0,new byte[4]));assertFalse(p.verify(c,new Response(r.auditId(),r.nonce(),r.fileId(),r.version(),r.objectLength(),mutated),m,1001).passed());}
 @Test void sampledCoverageAndUniqueIndices(){AuditProtocol p=new AuditProtocol();Manifest m=p.manifest("file",1,new byte[1000000]);Challenge c=p.challenge("a",m,"SAMPLED",1000);assertEquals(3,c.indices().size());assertEquals(3,new HashSet<>(c.indices()).size());assertEquals(m.blocks().size(),p.challenge("b",m,"FULL",1000).indices().size());}
 @Test void malformedNullProofIsRejected(){AuditProtocol p=new AuditProtocol();Manifest m=p.manifest("file",1,new byte[4]);Challenge c=p.challenge("a",m,"FULL",1000);assertFalse(p.verify(c,null,m,1001).passed());assertFalse(p.verify(null,null,null,1001).passed());Response r=new Response("a",c.nonce(),"file",1,4,List.of(new ResponseBlock(0,null)));assertFalse(p.verify(c,r,m,1001).passed());Challenge invalid=new Challenge("a",c.nonce(),"file",1,Arrays.asList((Integer)null),1000,2000,"FULL");assertFalse(p.verify(invalid,r,m,1001).passed());}
}
